"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import { useEffect } from "react";

const schema = z.object({
    name: z.string().min(3, "Nome deve ter pelo menos 3 caracteres"),
    external_id: z.string().optional(),
    base_cost: z.coerce.number().min(0, "Valor inválido"),
    table_id: z.coerce.number().min(1, "Selecione uma tabela"),
});

type FormData = z.infer<typeof schema>;

interface SupplierProductModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    initialData?: any;
    tables: any[];
    title: string;
}

export default function SupplierProductModal({ isOpen, onClose, onSubmit, initialData, tables, title }: SupplierProductModalProps) {
    const {
        register,
        handleSubmit,
        reset,
        formState: { errors, isSubmitting }
    } = useForm<FormData>({
        resolver: zodResolver(schema),
        defaultValues: {
            name: "",
            external_id: "",
            base_cost: 0,
            table_id: 0
        }
    });

    useEffect(() => {
        if (initialData) {
            reset(initialData);
        } else {
            reset({
                name: "",
                external_id: "",
                base_cost: 0,
                table_id: 0
            });
        }
    }, [initialData, reset, isOpen]);

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title} width="md">
            <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <div className="space-y-4">
                    <Input
                        label="Nome do Produto (no Fornecedor)"
                        {...register("name")}
                        error={errors.name?.message}
                        placeholder="Ex: Certificado A1 CPF"
                    />
                    <Input
                        label="ID Externo / Produto Fornecedor ID"
                        {...register("external_id")}
                        error={errors.external_id?.message}
                        placeholder="Ex: 504"
                    />
                    <div className="grid grid-cols-2 gap-4">
                        <Input
                            label="Custo Base (R$)"
                            type="number"
                            step="0.01"
                            {...register("base_cost")}
                            error={errors.base_cost?.message}
                            placeholder="0.00"
                        />
                        <div className="space-y-1">
                            <label className="text-[12px] font-bold text-[var(--foreground)]/80 px-1">Tabela de Custos</label>
                            <select
                                {...register("table_id")}
                                className="w-full h-11 px-4 bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-sm font-medium focus:ring-2 focus:ring-primary appearance-none cursor-pointer"
                            >
                                <option value={0}>Selecione...</option>
                                {tables.map((t: any) => (
                                    <option key={t.id} value={t.id}>{t.name}</option>
                                ))}
                            </select>
                            {errors.table_id && <p className="text-[10px] text-rose-500 font-bold px-1 mt-1">{errors.table_id.message}</p>}
                        </div>
                    </div>
                </div>

                <div className="flex justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-2 text-xs font-bold text-slate-500 hover:text-slate-700 transition-colors"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="bg-primary text-white px-8 py-2 rounded-xl text-xs font-bold shadow-lg shadow-primary/20 hover:bg-primary/90 transition-all disabled:opacity-50"
                    >
                        {isSubmitting ? "Salvando..." : "Salvar Produto Fornecedor"}
                    </button>
                </div>
            </form>
        </Modal>
    );
}
