"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import { useEffect } from "react";

const schema = z.object({
    name: z.string().min(3, "Nome deve ter pelo menos 3 caracteres"),
    external_id: z.string().optional(),
    tax_fixed: z.coerce.number().min(0, "Valor inválido"),
    tax_percent: z.coerce.number().min(0, "Valor inválido").max(100, "Máximo 100%"),
});

type FormData = z.infer<typeof schema>;

interface SupplierTableModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    initialData?: any;
    title: string;
}

export default function SupplierTableModal({ isOpen, onClose, onSubmit, initialData, title }: SupplierTableModalProps) {
    const {
        register,
        handleSubmit,
        reset,
        formState: { errors, isSubmitting }
    } = useForm<FormData>({
        resolver: zodResolver(schema),
        defaultValues: {
            name: "",
            external_id: "",
            tax_fixed: 0,
            tax_percent: 0
        }
    });

    useEffect(() => {
        if (initialData) {
            reset(initialData);
        } else {
            reset({
                name: "",
                external_id: "",
                tax_fixed: 0,
                tax_percent: 0
            });
        }
    }, [initialData, reset, isOpen]);

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title} width="md">
            <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <div className="space-y-4">
                    <Input
                        label="Nome da Tabela"
                        {...register("name")}
                        error={errors.name?.message}
                        placeholder="Ex: Tabela Direta Bradesco"
                    />
                    <Input
                        label="ID Externo (Opcional)"
                        {...register("external_id")}
                        error={errors.external_id?.message}
                        placeholder="Ex: TAB_501"
                    />
                    <div className="grid grid-cols-2 gap-4">
                        <Input
                            label="Taxa Fixa (R$)"
                            type="number"
                            step="0.01"
                            {...register("tax_fixed")}
                            error={errors.tax_fixed?.message}
                            placeholder="0.00"
                        />
                        <Input
                            label="Imposto (%)"
                            type="number"
                            step="0.01"
                            {...register("tax_percent")}
                            error={errors.tax_percent?.message}
                            placeholder="0.00"
                        />
                    </div>
                </div>

                <div className="flex justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-2 text-xs font-bold text-slate-500 hover:text-slate-700 transition-colors"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="bg-primary text-white px-8 py-2 rounded-xl text-xs font-bold shadow-lg shadow-primary/20 hover:bg-primary/90 transition-all disabled:opacity-50"
                    >
                        {isSubmitting ? "Salvando..." : "Salvar Tabela"}
                    </button>
                </div>
            </form>
        </Modal>
    );
}
