"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import SegmentedControl from "./ui/SegmentedControl";
import { useEffect } from "react";

const productSchema = z.object({
    name: z.string().min(3, "Nome do produto deve ter pelo menos 3 caracteres"),
    price: z.coerce.number().min(0.01, "Informe o preço"),
    commission: z.coerce.number().optional(),
    commission_bronze: z.coerce.number().min(0, "Informe a comissão Bronze"),
    commission_prata: z.coerce.number().min(0, "Informe a comissão Prata"),
    commission_ouro: z.coerce.number().min(0, "Informe a comissão Ouro"),
    category: z.string().min(2, "Informe a categoria"),
    type: z.string().min(2, "Informe o tipo (ex: A1, A3)"),
    media_type: z.enum(["Nuvem", "Token", "Cartão", "Arquivo"]),
    supplier_product_id: z.coerce.number().optional().nullable(),
});

type ProductFormData = z.infer<typeof productSchema>;

interface ProductModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: any) => void;
    initialData?: any;
    supplierProducts: any[];
    title: string;
}

export default function ProductModal({ isOpen, onClose, onSubmit, initialData, supplierProducts, title }: ProductModalProps) {
    const {
        register,
        handleSubmit,
        reset,
        watch,
        setValue,
        formState: { errors, isSubmitting }
    } = useForm<ProductFormData>({
        resolver: zodResolver(productSchema) as any,
    });

    useEffect(() => {
        if (initialData) {
            reset({
                ...initialData,
                media_type: initialData.media_type || "Nuvem",
                supplier_product_id: initialData.supplier_product_id || null
            });
        } else {
            reset({
                name: "",
                price: 0,
                commission_bronze: 0,
                commission_prata: 0,
                commission_ouro: 0,
                category: "CPF",
                type: "A1",
                media_type: "Nuvem",
                supplier_product_id: null
            });
        }
    }, [initialData, reset, isOpen]);

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title}>
            <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <Input
                    label="Nome do Produto / Certificado"
                    {...register("name")}
                    error={errors.name?.message}
                    placeholder="Ex: e-CPF A3 (3 Anos)"
                    helpText="Nomes claros aumentam a confiança do cliente no checkout."
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input
                        label="Preço de Venda (R$)"
                        type="number"
                        step="0.01"
                        {...register("price")}
                        error={errors.price?.message}
                        helpText="Preço final visível no checkout."
                    />
                    <div className="space-y-1">
                        <label className="text-[12px] font-bold text-[var(--foreground)]/80 px-1">Vínculo de Custo (Fornecedor)</label>
                        <select
                            {...register("supplier_product_id")}
                            className="w-full h-11 px-4 bg-slate-50 dark:bg-slate-800 border-none rounded-xl text-sm font-medium focus:ring-2 focus:ring-primary appearance-none cursor-pointer"
                        >
                            <option value="">Sem vínculo (Custo Zero)</option>
                            {supplierProducts.map((sp: any) => (
                                <option key={sp.id} value={sp.id}>{sp.name} (R$ {sp.base_cost})</option>
                            ))}
                        </select>
                        <p className="text-[10px] text-slate-400 font-medium px-1 mt-1 italic">Vincule para calcular lucro líquido real.</p>
                    </div>
                </div>

                <div className="p-4 bg-[var(--accent)]/30 rounded-2xl border border-[var(--border)] overflow-hidden">
                    <p className="text-[10px] font-black uppercase text-primary tracking-widest mb-4">Preços de Custo por Nível do Parceiro</p>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <Input
                            label="🥉 CUSTO BRONZE"
                            type="number"
                            step="0.01"
                            {...register("commission_bronze")}
                            error={errors.commission_bronze?.message}
                        />
                        <Input
                            label="🥈 CUSTO PRATA"
                            type="number"
                            step="0.01"
                            {...register("commission_prata")}
                            error={errors.commission_prata?.message}
                        />
                        <Input
                            label="🥇 CUSTO OURO"
                            type="number"
                            step="0.01"
                            {...register("commission_ouro")}
                            error={errors.commission_ouro?.message}
                        />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input
                        label="Categoria"
                        {...register("category")}
                        error={errors.category?.message}
                        placeholder="Ex: CPF, CNPJ, etc."
                    />
                    <Input
                        label="Tipo / Modelo"
                        {...register("type")}
                        error={errors.type?.message}
                        placeholder="Ex: A1, A3, Nuvem"
                    />
                </div>

                <SegmentedControl
                    label="Tipo de Mídia Padrão"
                    value={watch("media_type") || "Nuvem"}
                    onChange={(v) => setValue("media_type", v as any)}
                    options={[
                        { label: "Nuvem (A1)", value: "Nuvem" },
                        { label: "Token (A3)", value: "Token" },
                        { label: "Cartão (A3)", value: "Cartão" },
                        { label: "Arquivo", value: "Arquivo" },
                    ]}
                />

                <div className="flex flex-col-reverse md:flex-row justify-end gap-3 pt-6 border-t border-[var(--border)]">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-2.5 rounded-xl font-bold text-xs text-[var(--muted)] hover:text-[var(--foreground)] transition-all"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="flex-1 max-w-full md:max-w-[40%] bg-primary text-white px-8 py-3 rounded-xl font-bold text-sm shadow-lg shadow-primary/20 hover:bg-primary/90 active:scale-95 transition-all disabled:opacity-50"
                    >
                        {isSubmitting ? "Salvando..." : initialData ? "Salvar Alterações" : "Criar Produto"}
                    </button>
                </div>
            </form>
        </Modal>
    );
}
